import { chromium } from 'playwright'

const BASE = 'http://127.0.0.1:8081'
const browser = await chromium.launch()
const page = await browser.newPage()

const errs = []
page.on('pageerror', (e) => errs.push(`[pageerror] ${e.message}`))

// Seed token before any app script runs
await page.addInitScript(() => {
  sessionStorage.setItem('Admin-Token', 'stub-token')
  sessionStorage.setItem('name', '测试用户')
})

// Generic stubs so the app can reach the layout without a real backend
await page.route('**/api/**', async (route) => {
  const url = route.request().url()
  const ok = (data) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, msg: 'ok', ...data }) })
  if (url.includes('/portal/user/detail')) return ok({ data: { user: { userId: '1', userName: 'tester', nickName: '测试用户', deptName: '部门' }, roles: ['admin'], permissions: [] } })
  if (url.includes('/portal/user/profile')) return ok({ user: { userId: '1', userName: 'tester', nickName: '测试用户', deptName: '部门' }, roles: ['admin'], permissions: [] })
  if (url.includes('/role/detail') || url.includes('/dept/detail')) return ok({ data: null })
  if (url.includes('/menu/list')) return ok({ data: [] })
  if (url.includes('/permission/routes') || url.includes('/GenerateRoutes')) return ok({ data: [] })
  if (url.includes('/portal/user/')) return ok({ user: { userId: '1', userName: 'tester', nickName: '测试用户', deptName: '部门' }, roles: ['admin'], permissions: [] })
  if (url.includes('/system/user/page')) return ok({ data: { rows: [] } })
  return ok({ data: {}, rows: [], total: 0, user: { userId: '1', userName: 'tester', nickName: '测试用户' }, roles: ['admin'], permissions: [] })
})

await page.goto(`${BASE}/#/index`, { waitUntil: 'domcontentloaded', timeout: 40000 }).catch((e) => errs.push('goto ' + e.message))
