  skeletonVisible: (() => { const el = document.querySelector('.app-main-skeleton'); if (!el) return false; const st = getComputedStyle(el); return st.display !== 'none' && st.visibility !== 'hidden' })(),
  bodyLen: document.body.innerText.trim().length
}))
