await page.evaluate(() => { location.hash = '#/dashboard' }).catch(()=>{})
await page.waitForTimeout(3000)
const s2 = await page.evaluate(() => ({
  hash: location.hash,
  hasAppMainSkeleton: !!document.querySelector('.app-main-skeleton'),
  bodyLen: document.body.innerText.trim().length
}))
console.log('AFTER route change:', JSON.stringify(s2))

if (errs.length) console.log('ERRORS:\n' + [...new Set(errs)].slice(0, 10).join('\n'))
await browser.close()

// Minimal proof of the hasRenderedView stuck pattern in a persistent component.
// Simulates: mount once -> later a route change (reactive 'route' data changes) -> does view flag recover?
const Vue = require('vue')

function makeComp(withFix) {
  return {
    data() { return { hasRenderedView: false, route: '/a' } },
    computed: { skeleton() { return !this.hasRenderedView } },
    watch: {
      route() {
        this.hasRenderedView = false
        if (withFix) {
          this.$nextTick(() => { this.hasRenderedView = true })
        }
      }
    },
    mounted() {
      this.$nextTick(() => { this.hasRenderedView = true })
    },
    render(h) { return h('div', this.skeleton ? 'SKELETON' : 'CONTENT') }
  }
}

function run(withFix) {
  return new Promise((resolve) => {
    const vm = new (Vue.extend(makeComp(withFix)))().$mount()
    Vue.nextTick(() => {
      const init = vm.hasRenderedView
      // simulate a route change after mount (like guard replace / in-app nav)
      vm.route = '/b'
      Vue.nextTick(() => Vue.nextTick(() => {
        resolve({ withFix, initialRendered: init, afterRouteChangeRendered: vm.hasRenderedView, showsSkeleton: !vm.hasRenderedView })
        vm.$destroy()
      }))
    })
  })
}

;(async () => {
  console.log('WITHOUT fix:', JSON.stringify(await run(false)))
  console.log('WITH fix   :', JSON.stringify(await run(true)))
})()

