import { chromium } from 'playwright'
const browser = await chromium.launch()

async function run(cachedData, label) {
  const page = await browser.newPage()
  const errs = []
  page.on('pageerror', (e) => errs.push(`[pageerror] ${e.message}`))
  page.on('console', (m) => { if (m.type() === 'error') errs.push(`[err] ${m.text()}`) })
  await page.addInitScript((data) => {
    if (data) localStorage.setItem('platform-config-cache', data)
    else localStorage.removeItem('platform-config-cache')
  }, cachedData)
  const t0 = Date.now()
  await page.goto('http://localhost:8081/', { waitUntil: 'domcontentloaded', timeout: 45000 }).catch((e)=>errs.push('goto '+e.message))
  let clearedAt = null, sawSkeleton = false
  for (let i = 0; i < 150; i++) {
    const s = await page.evaluate(() => ({ hasSk: !!document.querySelector('.page-skeleton'), len: document.body.innerText.trim().length }))
    if (s.hasSk) sawSkeleton = true
    if (clearedAt === null && !s.hasSk && s.len > 100) clearedAt = Date.now() - t0
    await page.waitForTimeout(100)
    if (i === 60) break // ~6s
  }
  const final = await page.evaluate(() => ({ hasPageSkeleton: !!document.querySelector('.page-skeleton'), bodyLen: document.body.innerText.trim().length, hash: location.hash }))
  console.log(`### ${label}: sawSkeleton=${sawSkeleton} clearedAt=${clearedAt}ms final=${JSON.stringify(final)}`)
  if (errs.length) console.log('  ERRS:', [...new Set(errs)].slice(0,6).join(' | '))
  await page.close()
}

// Simulate a plausible cache the real app writes: {data:{...}, savedAt}
const goodCache = JSON.stringify({ data: { platformName: '苏州房产综合服务平台', region: '320500', sysLogo: '/zhi2/x.png', buttonDefaultColor: '#1677FF' }, savedAt: Date.now() })
await run(null, 'no cache')
await run(goodCache, 'valid cache')
await run('{bad json', 'corrupt cache')
await run(JSON.stringify({ data: {}, savedAt: Date.now() }), 'empty-data cache')
await browser.close()

