// hex颜色转rgb颜色
export function hexToRgb(str) {
  // 容错：入参可能为空或非法（如样式尚未加载时 getCssVariable 返回空串，
  // 或配置里给了非 6 位 hex），此时 match 会得到 null，原实现会抛
  // "Cannot read properties of null (reading '0')" 并中断整个应用启动。这里退化为黑色。
  const source = String(str == null ? '' : str).replace("#", "");
  const hexs = source.match(/../g);
  if (!hexs || hexs.length < 3) {
    return [0, 0, 0];
  }
  const result = [0, 0, 0];
  for (let i = 0; i < 3; i++) {
    result[i] = parseInt(hexs[i], 16) || 0;
  }

  return result;
}

